/**
 * Parse a URI reference into its components
 * Returns { scheme, authority, path, query, fragment }
 */
function parseURI(uri) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  let remaining = uri
  let pos = 0

  // Parse fragment first (from the end)
  const fragmentPos = uri.indexOf('#')
  if (fragmentPos !== -1) {
    fragment = uri.substring(fragmentPos + 1)
    remaining = uri.substring(0, fragmentPos)
  }

  // Parse query
  const queryPos = remaining.indexOf('?')
  if (queryPos !== -1) {
    query = remaining.substring(queryPos + 1)
    remaining = remaining.substring(0, queryPos)
  }

  // Parse scheme: runs to first ':' not preceded by '/', '?', '#'
  let schemeEnd = -1
  for (let i = 0; i < remaining.length; i++) {
    const char = remaining[i]
    if (char === ':') {
      schemeEnd = i
      break
    }
    if (char === '/' || char === '?' || char === '#') {
      break
    }
  }

  if (schemeEnd !== -1) {
    scheme = remaining.substring(0, schemeEnd)
    remaining = remaining.substring(schemeEnd + 1)
  }

  // Parse authority: starts with '//', runs to next '/', '?', '#'
  if (remaining.startsWith('//')) {
    let authorityEnd = -1
    for (let i = 2; i < remaining.length; i++) {
      const char = remaining[i]
      if (char === '/' || char === '?' || char === '#') {
        authorityEnd = i
        break
      }
    }
    if (authorityEnd === -1) {
      authority = remaining.substring(2)
      remaining = ''
    } else {
      authority = remaining.substring(2, authorityEnd)
      remaining = remaining.substring(authorityEnd)
    }
  }

