 * Uses a segment-based approach to correctly handle trailing slashes
 */
function removeDotSegments(path) {
  if (!path) return path

  // Split into segments, preserving information about trailing slash
  const hasTrailingSlash = path.endsWith('/')
  const segments = path.split('/')
  const result = []

  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i]

    if (segment === '' || segment === '.') {
      // Empty segment (from leading slash or doubled slashes) or '.' segment
      // Keep the first empty segment (leading slash)
      if (i === 0) {
        result.push(segment)
      }
      // Don't keep middle empty segments or '.' segments
