      // '..' removes the previous segment if it's not the root
      if (result.length > 0 && !(result.length === 1 && result[0] === '')) {
        result.pop()
      }
      // '..' that climbs above root is discarded (do nothing)
    } else {
      // Regular segment
      result.push(segment)
    }
  }

  // Preserve the trailing slash from the original path
  let output = result.join('/')
  if (hasTrailingSlash && !output.endsWith('/')) {
    output += '/'
  }

  return output
}

